      if (c === '"') { inStr = true; continue; }
      if (c === '{') stack.push('}');
      else if (c === '[') stack.push(']');
      else if (c === '}' || c === ']') { stack.pop(); goods.push({ end: k + 1, closers: stack.slice() }); }
      else if (/[0-9el]/.test(c)) goods.push({ end: k + 1, closers: stack.slice() });
    }
    for (let g = goods.length - 1, tries = 0; g >= 0 && tries < 120; g--, tries++) {
      const cand = t.substring(0, goods[g].end) + goods[g].closers.slice().reverse().join('');
      try { return JSON.parse(cand); } catch(e2) {}
    }
  } catch(e3) {}
  return null;
}

