sql_parts.push(`INSERT INTO giulia_memoria (from_numero, role, content, metadata) VALUES ('${esc(sender)}', 'user', '${texto_user}', NULL), ('${esc(sender)}', 'assistant', '${resposta}', NULL);`);

// 2. Facts novos sobre o Thiago
for (const f of facts_novos) {
  if (!f || !f.fact) continue;
  const cat = f.categoria ? `'${esc(f.categoria)}'` : 'NULL';
  sql_parts.push(`INSERT INTO giulia_facts (about_numero, fact, categoria, fonte) VALUES ('${esc(sender)}', '${esc(f.fact)}', ${cat}, 'conversa') ON CONFLICT (about_numero, fact) DO UPDATE SET atualizado_em = NOW(), ativo = TRUE;`);
}

// 3. confirmar_envio: marca enviado OU erro conforme resultado real do envio
if (acao === 'confirmar_envio' && envio_id) {
  const st = frf.envio_falhou ? 'erro' : 'enviado';
  sql_parts.push(`UPDATE giulia_envios_pendentes SET status = '${st}', enviado_em = NOW() WHERE id = ${parseInt(envio_id,10)};`);
}

// 4. alerta tecnico pro Thiago quando falha em conversa de OUTRO dono (dedup 30 min)
if ((frf.parse_falhou || frf.envio_falhou) && frf.eh_thiago && sender !== '5511910441709') {
  const tipoAl = frf.parse_falhou ? 'IA respondeu fora do formato (mesmo apos retry)' : 'falha ao executar/entregar acao';
  const alerta = 'Alerta tecnico: ' + tipoAl + ' na conversa com ' + sender + '. Ultima resposta: ' + String(frf.resposta_final || '').substring(0, 90).replace(/'/g, '');
  sql_parts.push(`INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para, status) SELECT '5511910441709', 'Thiago', '\u26a0\ufe0f ${esc(alerta)}', NOW() AT TIME ZONE 'America/Sao_Paulo', 'pendente' WHERE NOT EXISTS (SELECT 1 FROM giulia_mensagens_agendadas WHERE destinatario_numero = '5511910441709' AND conteudo LIKE '\u26a0\ufe0f Alerta tecnico%' AND criado_em > NOW() - INTERVAL '30 minutes');`);
}

